insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000010', 'en', null, 'Design Thinking & Innovation', 'A hands-on tour of human-centered design — from understanding real users to shipping a tested prototype. Built from openly-licensed OER Commons material (CC BY) and organized around the Stanford d.school / IDEO five-stage model: empathize, define, ideate, prototype, test.', null, 'work', 16, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000010', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Design thinking is best described as…","options":["a graphic-design style","a human-centered approach to solving problems","a project-management chart","a coding methodology"],"answer":1,"explanation":"Design thinking starts from human needs, not from a preferred solution — see ''What design thinking is''."},{"prompt":"The five stages of the d.school model, in order, are…","options":["plan, build, launch, market, sell","empathize, define, ideate, prototype, test","research, design, develop, deploy, review","observe, sketch, vote, ship, forget"],"answer":1,"explanation":"Empathize → Define → Ideate → Prototype → Test — the backbone of the whole course."},{"prompt":"The main goal of the Empathize stage is to…","options":["pick the final solution","understand users'' real needs and context","build a working product","write the marketing copy"],"answer":1,"explanation":"You gather deep insight before deciding anything — see ''Empathize''."},{"prompt":"A good point-of-view (POV) statement produced in Define names…","options":["a user, a need, and an insight","a budget and a deadline","a competitor and a price","a color palette"],"answer":0,"explanation":"User + need + insight frames the problem — see ''Define''."},{"prompt":"During a brainstorm, the rule ''defer judgment'' means…","options":["ignore the user","generate many ideas before critiquing them","let the boss decide","only accept realistic ideas"],"answer":1,"explanation":"Divergent thinking first, evaluation later — see ''Ideate''."},{"prompt":"A prototype in design thinking is best when it is…","options":["polished and final","quick, cheap, and just real enough to test","kept secret from users","a written report"],"answer":1,"explanation":"Low-fidelity prototypes let you learn fast and cheaply — see ''Prototype''."},{"prompt":"The purpose of the Test stage is mainly to…","options":["prove you were right","learn from users and improve the idea","finalize the invoice","impress investors"],"answer":1,"explanation":"Testing is about learning, not defending — see ''Test & iterate''."},{"prompt":"The design thinking process is best understood as…","options":["strictly linear, one pass","iterative — you loop back as you learn","done only once at the start","a solo activity"],"answer":1,"explanation":"Teams revisit earlier stages as insight grows — a core theme all course."}]}'::jsonb, null, 10),
  (2, 'What design thinking is (and the mindset)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what design thinking is and describe the mindset behind it. Warm-up: from the diagnostic, what are the five stages in order?"},{"heading":"The idea","text":"Design thinking is a *human-centered* way to solve problems: you start from real people''s needs, not from a solution you already like. The Stanford d.school and IDEO describe five modes — *empathize* (understand people), *define* (frame the right problem), *ideate* (generate many options), *prototype* (make ideas tangible), and *test* (learn from users). The process is *iterative*: you loop back whenever a test teaches you something new. The mindset matters as much as the steps: stay curious, embrace ambiguity, be *bias-toward-action* (make something you can react to), and treat early failure as cheap learning."},{"heading":"Worked example","text":"A team wants to ''redesign the office coffee machine''. A solution-first team argues about machine brands. A design-thinking team instead watches people at 8am and discovers the real pain isn''t the machine — it''s the 6-minute queue. Reframing from ''better machine'' to ''shorter wait'' opens far better ideas. That reframe is the whole value of starting human-centered."},{"heading":"Your turn","text":"For each, say which mindset is at work: (1) building a cardboard mock-up in an hour instead of debating for a week; (2) interviewing users before proposing anything; (3) writing 30 ideas before judging any. Answers: (1) bias toward action; (2) empathy / human-centered; (3) defer judgment (divergent thinking)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating the five stages as a strict one-way line (they loop). Mistake: falling in love with your first solution. Exit: (a) What does ''human-centered'' mean in one phrase? (b) Is the process linear or iterative? Answers: start from real user needs; iterative."}]}'::jsonb, 'Solve the right problem before you solve the problem right.', 12),
  (3, 'Empathize: user research and empathy maps', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Run basic user research and fill in an empathy map. Warm-up: why might what a user says differ from what they actually do?"},{"heading":"The idea","text":"Empathize means understanding users deeply before deciding anything. Three core methods: *interview* (ask open ''why'' questions, not leading ones), *observe* (watch real behavior in context), and *immerse* (try the experience yourself). A helpful tool is the *empathy map* — four quadrants for what the user Says, Thinks, Does, and Feels. Watch especially for *gaps* between Says and Does and for *pain points* (frustrations) and *gains* (hopes). The goal is insight, not a feature list."},{"heading":"Worked example","text":"Designing a hospital check-in kiosk, the team interviews patients (''it''s fine'') but observes them hovering, unsure where to stand (Does ≠ Says). The empathy map captures: Says ''it''s easy''; Does hesitates and looks around; Thinks ''am I in the right line?''; Feels anxious about being judged for asking. That Feels quadrant — anxiety — becomes the real design target."},{"heading":"Your turn","text":"Sort these into empathy-map quadrants (Says / Thinks / Does / Feels): (1) ''I love this app''; (2) taps back-button repeatedly; (3) worried about looking stupid; (4) silently wonders if it saved. Answers: (1) Says; (2) Does; (3) Feels; (4) Thinks."},{"heading":"Common mistakes & exit ticket","text":"Mistake: asking leading questions (''Don''t you love this?''). Mistake: trusting stated opinions over observed behavior. Exit: (a) Name the four empathy-map quadrants. (b) Which quadrant often reveals the deepest need? Answers: Says/Thinks/Does/Feels; Feels."}]}'::jsonb, 'Observe what people do, not just what they say they do.', 13),
  (4, 'Define: framing the problem and the POV', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Turn research into a sharp problem statement and a ''How Might We'' question. Warm-up: what three parts belong in a point-of-view statement?"},{"heading":"The idea","text":"Define synthesizes empathy research into one clear, actionable problem to solve. The key tool is the *point-of-view (POV)* statement: ''[User] needs [need] because [surprising insight].'' The need is a verb (something to accomplish), not a noun (a solution). A good POV is then reframed into *How Might We (HMW)* questions that are neither too broad nor too narrow — they open space for ideas without smuggling in the answer. Define is the hinge between understanding and creating: get it wrong and every later stage solves the wrong thing."},{"heading":"Worked example","text":"From the kiosk research: a weak POV is ''patients need a bigger touchscreen'' — that''s a solution disguised as a need. A strong POV: ''An anxious first-time patient needs to feel confident they''re doing check-in correctly, because the fear of doing it wrong in public outweighs the task itself.'' HMW: ''How might we reassure patients they''re on the right track at every step?'' — broad enough for many ideas, narrow enough to aim."},{"heading":"Your turn","text":"Fix each broken POV. (1) ''Users need a mobile app.'' (2) ''Commuters need a faster train.'' Rewrite as user + verb-need + insight. Sample answers: (1) ''A busy user needs to check status *in seconds* because they only glance while walking''; (2) ''A stressed commuter needs to *trust the arrival time* because uncertainty, not speed, causes the anxiety.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing a solution into the need (''needs a button''). Mistake: an HMW so broad (''how might we fix healthcare'') that nothing follows. Exit: (a) A need should be a verb or a noun? (b) What are the three parts of a POV? Answers: a verb; user, need, insight."}]}'::jsonb, 'A problem well framed is half solved.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The first stage of the d.school model is…","options":["Prototype","Empathize","Define","Test"],"answer":1,"explanation":"You understand people before anything else."},{"prompt":"An empathy map has four quadrants: Says, Thinks, Does, and…","options":["Buys","Feels","Sells","Plans"],"answer":1,"explanation":"Says / Thinks / Does / Feels."},{"prompt":"A gap between what a user Says and what they Do usually signals…","options":["the user is lying","a hidden or unspoken need","bad data to discard","nothing important"],"answer":1,"explanation":"The gap often points to the real, unspoken need."},{"prompt":"In a point-of-view statement, the ''need'' should be expressed as…","options":["a specific product","a verb / something to accomplish","a price point","a color"],"answer":1,"explanation":"Needs are verbs, not solutions."},{"prompt":"''How Might We…'' questions are used to…","options":["close down options","reframe a POV into an open design brief","assign blame","estimate cost"],"answer":1,"explanation":"HMW opens idea space without dictating the answer."},{"prompt":"The Define stage sits between which two stages?","options":["Test and Empathize","Empathize and Ideate","Ideate and Prototype","Prototype and Test"],"answer":1,"explanation":"Define turns empathy insight into a problem to ideate on."}]}'::jsonb, null, 8),
  (6, 'Ideate: brainstorming and divergent/convergent thinking', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Run a productive brainstorm and separate divergent from convergent thinking. Warm-up: why is judging ideas too early harmful?"},{"heading":"The idea","text":"Ideate is where you generate a wide range of options for your HMW question. It has two beats: *divergent thinking* (go wide — produce many varied ideas) and *convergent thinking* (go narrow — cluster, evaluate, and select). Keep them separate; mixing them kills creativity. Classic brainstorm rules (IDEO): *defer judgment*, *encourage wild ideas*, *build on others'' ideas* (''yes, and…''), *stay on topic*, *one conversation at a time*, and *go for quantity*. Techniques include ''Worst Possible Idea'', SCAMPER, and brainwriting. To converge, use dot-voting or a 2×2 (impact vs. effort) to pick a few ideas worth prototyping."},{"heading":"Worked example","text":"For ''reassure patients during check-in'', a team generates 40 ideas in 10 minutes — including silly ones like ''a talking robot greeter''. Deferring judgment kept the flow going; the wild robot idea later shrank into a realistic winner: a friendly on-screen progress bar (''Step 2 of 3 — you''re doing it right''). Then dot-voting on a 2×2 selected three high-impact, low-effort ideas to prototype."},{"heading":"Your turn","text":"Label each move divergent (D) or convergent (C): (1) sticky-noting 30 ideas fast; (2) grouping them into themes; (3) ''yes, and…'' building on a teammate''s idea; (4) dot-voting the top three. Answers: (1) D; (2) C; (3) D; (4) C."},{"heading":"Common mistakes & exit ticket","text":"Mistake: critiquing ideas while still generating them (converging too soon). Mistake: stopping at the first ''good enough'' idea. Exit: (a) Which comes first, diverge or converge? (b) Name one brainstorm rule. Answers: diverge; e.g. defer judgment / go for quantity."}]}'::jsonb, 'Go wide before you go deep: diverge, then converge.', 13),
  (7, 'Prototype: rapid, low-fidelity making', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Choose an appropriately rough prototype and know what question it should answer. Warm-up: why build something cheap and unfinished on purpose?"},{"heading":"The idea","text":"Prototype means making an idea *tangible* so people can react to it. The rule is *low fidelity*: paper sketches, cardboard, storyboards, role-play, or a clickable mock-up — just real enough to test one specific question. Cheap and rough is a feature: you stay unattached, you learn faster, and users critique the idea instead of politely admiring a polished thing. Every prototype should target a *learning goal* (''will users understand the progress steps?''). Fidelity rises only as uncertainty falls."},{"heading":"Worked example","text":"Instead of coding the kiosk, the team tapes paper ''screens'' to a wall and a teammate plays the computer, swapping pages as a test user ''taps''. In 20 minutes they learn that patients miss the confirmation step entirely — a fix that would have cost days to discover in real code. The ugliness of paper is exactly why testers gave honest, blunt feedback."},{"heading":"Your turn","text":"Match each idea to a fitting low-fi prototype: (1) a new app flow; (2) a physical waiting-room layout; (3) a conversation script for staff. Options: paper/clickable wireframe, cardboard scale model, role-play. Answers: (1) paper/clickable wireframe; (2) cardboard scale model; (3) role-play."},{"heading":"Common mistakes & exit ticket","text":"Mistake: over-polishing so testers won''t ''hurt'' it (they''ll go easy on you). Mistake: prototyping with no clear question in mind. Exit: (a) Why keep prototypes low-fidelity? (b) What must every prototype have? Answers: to learn fast and stay unattached; a specific learning goal / question."}]}'::jsonb, 'Build to think and to test — not to impress.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"empathy map","translation":"a four-quadrant tool capturing what a user Says, Thinks, Does, and Feels","example":"The empathy map showed patients felt anxious even when they said check-in was ''fine''."},{"term":"point-of-view (POV)","translation":"a problem statement in the form ''user + need + insight'' that frames what to solve","example":"Their POV named an anxious first-time patient who needs reassurance."},{"term":"How Might We (HMW)","translation":"an open question that reframes a POV into a brief for ideation","example":"''How might we reassure patients at every step?'' guided the brainstorm."},{"term":"divergent thinking","translation":"generating many varied ideas without judging them yet","example":"They used divergent thinking to reach 40 ideas in ten minutes."},{"term":"convergent thinking","translation":"narrowing many ideas down by clustering and evaluating to pick the best","example":"Dot-voting on a 2×2 was their convergent thinking step."},{"term":"low-fidelity prototype","translation":"a quick, rough, cheap version of an idea made just real enough to test","example":"A paper low-fidelity prototype revealed the missing confirmation step in minutes."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Divergent thinking is about…","options":["picking one final idea","generating many varied ideas","estimating budgets","writing the report"],"answer":1,"explanation":"Diverge = go wide, generate options."},{"prompt":"Which is a classic brainstorm rule?","options":["Judge each idea immediately","Defer judgment","One person speaks all session","Only realistic ideas allowed"],"answer":1,"explanation":"Defer judgment keeps ideas flowing."},{"prompt":"A prototype should mainly be…","options":["polished and expensive","low-fidelity and quick to test","hidden from users","the final product"],"answer":1,"explanation":"Low-fi lets you learn fast and cheap."},{"prompt":"Converging on ideas might use…","options":["dot-voting or an impact/effort 2×2","adding more wild ideas","ignoring the users","raising the budget"],"answer":0,"explanation":"Convergence clusters and selects."},{"prompt":"Every prototype should be built to answer…","options":["a specific learning question","the CEO''s preference","a marketing slogan","nothing in particular"],"answer":0,"explanation":"Prototypes target a learning goal."},{"prompt":"Keeping prototypes rough helps because testers…","options":["admire the craftsmanship","give more honest, blunt feedback","cannot understand them","feel it''s already finished"],"answer":1,"explanation":"People critique rough things honestly."}]}'::jsonb, null, 8),
  (10, 'Applied project: run a mini design-thinking sprint', 'writing', '{"sections":[{"heading":"The task","text":"Pick a small, real problem you can observe this week — a confusing sign-up form, a messy shared kitchen, a group chat that never decides anything. You''ll run a compact sprint through all five stages: empathize, define, ideate, prototype, test. You won''t build a product; you''ll practice the full loop rigorously and cheaply."},{"heading":"Milestones","text":"1) EMPATHIZE — interview or observe at least two real people; fill a quick empathy map (Says/Thinks/Does/Feels). 2) DEFINE — write one POV (''user + verb-need + insight'') and one ''How Might We'' question. 3) IDEATE — brainstorm at least 15 ideas with judgment deferred, then converge to your top three. 4) PROTOTYPE — make one low-fidelity prototype (paper, sketch, or role-play) aimed at a specific question. 5) TEST — show it to one real user, note what surprised you, and name the one change you''d make next loop."},{"heading":"Self-check rubric","text":"✔ Empathy came from a real person, not your assumptions. ✔ Your need is a verb, and the POV includes a genuine insight. ✔ You clearly separated diverging (many ideas) from converging (selecting). ✔ The prototype was rough, fast, and targeted one learning question. ✔ Testing produced at least one surprise and a concrete next iteration. If all five are true, you''ve completed a real design-thinking loop — and proven the process is iterative, not linear."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000010' and l.position = v.pos
);
